module apb_timer (
    input  logic        PCLK,
    input  logic        PRESETn,
    input  logic        PSEL,
    input  logic        PENABLE,
    input  logic        PWRITE,
    input  logic [7:0]  PADDR,
    input  logic [31:0] PWDATA,
    output logic [31:0] PRDATA,
    output logic        PREADY,
    output logic        PSLVERR,
    output logic        irq
);
    // ---------------- architectural state (spec section 6) ----------------
    logic        en, mode, ie, pend, ovf;
    logic [7:0]  psc, pcnt;
    logic [15:0] shadow, active, count;

    // ---------------- APB decode (R-APB-1, 4, 8) ----------------
    logic       acc, is_rd, is_wr, unmapped, ro, err;
    logic [5:0] word;
    assign acc      = PSEL & PENABLE;
    assign word     = PADDR[7:2];
    assign is_rd    = acc & ~PWRITE;
    assign is_wr    = acc &  PWRITE;
    assign unmapped = (word > 6'd6);
    assign ro       = (word == 6'd2) | (word == 6'd5) | (word == 6'd6);
    assign err      = acc & (unmapped | (PWRITE & ro));

    logic w_ctrl, w_load, w_stat, w_cmd;
    assign w_ctrl = is_wr & ~err & (word == 6'd0);
    assign w_load = is_wr & ~err & (word == 6'd1);
    assign w_stat = is_wr & ~err & (word == 6'd3);
    assign w_cmd  = is_wr & ~err & (word == 6'd4);

    // ---------------- events (spec section 8.1) ----------------
    logic tick, expire, start, rcmd;
    assign tick   = en & (pcnt == psc);
    assign expire = tick & (count == 16'd0);
    assign start  = w_ctrl & PWDATA[0] & ~en;
    assign rcmd   = w_cmd  & PWDATA[0];

    // ---------------- outputs (R-APB-3, 6, 7, 8; R-INT-6) ----------------
    assign PREADY  = 1'b1;
    assign PSLVERR = err;
    assign irq     = pend & ie;
    always_comb begin
        PRDATA = 32'h0;
        if (is_rd & ~unmapped) begin
            unique case (word)
                6'd0: PRDATA = {16'h0, psc, 5'h0, ie, mode, en};
                6'd1: PRDATA = {16'h0, shadow};
                6'd2: PRDATA = {16'h0, count};
                6'd3: PRDATA = {30'h0, ovf, pend};
                6'd4: PRDATA = 32'h0;
                6'd5: PRDATA = {16'h0, active};
                6'd6: PRDATA = {24'h0, pcnt};
                default: PRDATA = 32'h0;
            endcase
        end
    end

    // ---------------- next-state, one field at a time (section 10) ----------------
    logic        en_n, mode_n, ie_n, pend_n, ovf_n;
    logic [7:0]  psc_n, pcnt_n;
    logic [15:0] shadow_n, active_n, count_n;

    always_comb begin
        // R-PRI-6: MODE, IE, PSC change only on a successful CTRL write
        mode_n = w_ctrl ? PWDATA[1]    : mode;
        ie_n   = w_ctrl ? PWDATA[2]    : ie;
        psc_n  = w_ctrl ? PWDATA[15:8] : psc;
        // R-PRI-7 / R-TMR-11: SHADOW changes only on a successful LOAD write
        shadow_n = w_load ? PWDATA[15:0] : shadow;
        // R-PRI-2: one-shot completion > CTRL write > hold
        if (expire & mode)  en_n = 1'b0;
        else if (w_ctrl)    en_n = PWDATA[0];
        else                en_n = en;
        // R-PRI-3: start/restart > expiration effect > tick/prescaler > hold
        active_n = active;
        count_n  = count;
        pcnt_n   = pcnt;
        if (start | rcmd) begin
            active_n = shadow;          // reload transfer uses held SHADOW
            count_n  = shadow;
            pcnt_n   = 8'd0;
        end else if (en) begin
            pcnt_n = tick ? 8'd0 : pcnt + 8'd1;          // R-TMR-1
            if (expire) begin
                if (!mode) begin active_n = shadow; count_n = shadow; end  // R-TMR-4
                // one-shot: COUNT stays 0, ACTIVE unchanged (R-TMR-5)
            end else if (tick) begin
                count_n = count - 16'd1;                  // R-TMR-3
            end
        end
        // R-PRI-4 / R-INT-1,2
        pend_n = expire ? 1'b1 : ((w_stat & PWDATA[0]) ? 1'b0 : pend);
        // R-PRI-5 / R-INT-3,4 (set condition reads HELD pend)
        ovf_n  = (expire & pend) ? 1'b1 : ((w_stat & PWDATA[1]) ? 1'b0 : ovf);
    end

    // ---------------- state registers, async active-low reset (R-RST-1..3) ----------------
    always_ff @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            en <= 1'b0; mode <= 1'b0; ie <= 1'b0; psc <= 8'd0;
            shadow <= 16'd0; active <= 16'd0; count <= 16'd0;
            pcnt <= 8'd0; pend <= 1'b0; ovf <= 1'b0;
        end else begin
            en <= en_n; mode <= mode_n; ie <= ie_n; psc <= psc_n;
            shadow <= shadow_n; active <= active_n; count <= count_n;
            pcnt <= pcnt_n; pend <= pend_n; ovf <= ovf_n;
        end
    end
endmodule
